CREATE TYPE "tax_report_kind" AS ENUM ('sales_tax', 'purchase_tax', 'pp30', 'pnd3', 'pnd53', 'wht_issued_register', 'wht_received_register');

-- CreateEnum
CREATE TYPE "tax_report_status" AS ENUM ('draft', 'final', 'filed');

-- CreateEnum
CREATE TYPE "tax_calendar_status" AS ENUM ('open', 'done');

