    "fiscal_period_id" BIGINT NOT NULL,
    "status" "tax_report_status" NOT NULL DEFAULT 'draft',
    "generated_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "generated_by" BIGINT,
    "totals" JSONB NOT NULL,
    "lines" JSONB NOT NULL,
    "line_count" INTEGER NOT NULL,
    "report_amount" DECIMAL(14,2) NOT NULL,
    "gl_amount" DECIMAL(14,2) NOT NULL,
    "gl_difference" DECIMAL(14,2) NOT NULL,
    "file_object_ids" BIGINT[] NOT NULL DEFAULT ARRAY[]::BIGINT[],
    "finalised_at" TIMESTAMPTZ(6),
    "finalised_by" BIGINT,
    "filed_at" TIMESTAMPTZ(6),
    "filing_ref" TEXT,
    "paid_on" DATE,
    "paid_amount" DECIMAL(14,2),
    "company_bank_account_id" BIGINT,
    "row_version" INTEGER NOT NULL DEFAULT 1,

    CONSTRAINT "pk_tax_reports" PRIMARY KEY ("id")
);

