-- --- hand-written ------------------------------------------------------------------------------------------

ALTER TABLE tax_reports
  ADD CONSTRAINT ck_tax_reports__difference CHECK (gl_difference = gl_amount - report_amount),
  -- §7 step 7: a report is final only when it agrees with its GL control accounts.
  ADD CONSTRAINT ck_tax_reports__final CHECK (status = 'draft' OR (gl_difference = 0 AND finalised_at IS NOT NULL AND finalised_by IS NOT NULL)),
  ADD CONSTRAINT ck_tax_reports__filed CHECK ((status = 'filed') = (filed_at IS NOT NULL)),
  ADD CONSTRAINT ck_tax_reports__paid CHECK (
    (paid_on IS NULL) = (paid_amount IS NULL) AND (paid_on IS NULL OR (status <> 'draft' AND paid_amount >= 0 AND company_bank_account_id IS NOT NULL))),
  ADD CONSTRAINT ck_tax_reports__payable_kind CHECK (paid_on IS NULL OR kind IN ('pp30', 'pnd3', 'pnd53')),
  ADD CONSTRAINT ck_tax_reports__lines CHECK (jsonb_typeof(lines) = 'array' AND jsonb_typeof(totals) = 'object' AND line_count >= 0);

-- A final or filed report keeps its figures: only filing (final → filed) and payment are recorded on it.
CREATE FUNCTION tg_tax_reports__frozen() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'a final tax report cannot be deleted' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.status <> 'draft' AND (
       NEW.kind IS DISTINCT FROM OLD.kind OR NEW.entity_id IS DISTINCT FROM OLD.entity_id
    OR NEW.fiscal_period_id IS DISTINCT FROM OLD.fiscal_period_id OR NEW.totals IS DISTINCT FROM OLD.totals
    OR NEW.lines IS DISTINCT FROM OLD.lines OR NEW.line_count IS DISTINCT FROM OLD.line_count
    OR NEW.report_amount IS DISTINCT FROM OLD.report_amount OR NEW.gl_amount IS DISTINCT FROM OLD.gl_amount
    OR NEW.gl_difference IS DISTINCT FROM OLD.gl_difference OR NEW.generated_at IS DISTINCT FROM OLD.generated_at
    OR NEW.finalised_at IS DISTINCT FROM OLD.finalised_at OR NEW.finalised_by IS DISTINCT FROM OLD.finalised_by
    OR NOT (NEW.file_object_ids @> OLD.file_object_ids)
    OR (NEW.status = 'draft')
    OR (OLD.status = 'filed' AND NEW.status <> 'filed')
    OR (OLD.filed_at IS NOT NULL AND (NEW.filed_at IS DISTINCT FROM OLD.filed_at OR NEW.filing_ref IS DISTINCT FROM OLD.filing_ref))
    OR (OLD.paid_on IS NOT NULL AND (NEW.paid_on IS DISTINCT FROM OLD.paid_on OR NEW.paid_amount IS DISTINCT FROM OLD.paid_amount
        OR NEW.company_bank_account_id IS DISTINCT FROM OLD.company_bank_account_id))
  ) THEN
    RAISE EXCEPTION 'a final tax report keeps its figures' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER tg_tax_reports__frozen BEFORE UPDATE OR DELETE ON tax_reports
  FOR EACH ROW EXECUTE FUNCTION tg_tax_reports__frozen();

ALTER TABLE tax_calendar_items
  ADD CONSTRAINT ck_tax_calendar_items__kind CHECK (kind IN ('pp30', 'pnd3', 'pnd53')),
  ADD CONSTRAINT ck_tax_calendar_items__done CHECK ((status = 'done') = (done_at IS NOT NULL));
CREATE TRIGGER tg_tax_calendar_items__no_delete BEFORE DELETE ON tax_calendar_items
  FOR EACH ROW EXECUTE FUNCTION tg_forbid_delete();
